import os
from flask import Flask, request, jsonify

app = Flask(__name__)

DATA_DIR = "/data"

@app.route("/search", methods=["POST"])
def search():
    data = request.get_json()
    if not data:
        return jsonify({"error": "Invalid input"}), 400

    search_content = data.get("search_content")
    search_filename = data.get("search_filename")
    search_dir = data.get("search_dir")

    # Validate that at least one search parameter is provided
    if search_content is None and search_filename is None:
        return jsonify({"error": "Invalid input: at least one of search_content or search_filename must be provided"}), 400

    # Determine the directory to search in
    if search_dir:
        # Resolve the search directory, ensuring it's within /data
        target_dir = os.path.join(DATA_DIR, search_dir)
        # Security check: prevent path traversal outside /data
        if not os.path.abspath(target_dir).startswith(os.path.abspath(DATA_DIR)):
            return jsonify({"error": "Invalid search directory"}), 400
    else:
        target_dir = DATA_DIR

    # Check if the target directory exists
    if not os.path.isdir(target_dir):
        return jsonify({"files": []})

    matched_files = []

    # Walk through the directory
    for root, dirs, files in os.walk(target_dir):
        for filename in files:
            filepath = os.path.join(root, filename)

            # Check filename match
            filename_match = False
            if search_filename is not None:
                # Check if the filename starts with the search term
                if filename.startswith(search_filename):
                    filename_match = True

            # Check content match
            content_match = False
            if search_content is not None:
                try:
                    with open(filepath, "r", errors="ignore") as f:
                        content = f.read()
                        if search_content in content:
                            content_match = True
                except (IOError, OSError):
                    # Skip files that cannot be read
                    pass

            # Include the file if it matches either criteria
            if filename_match or content_match:
                matched_files.append(filepath)

    return jsonify({"files": matched_files})


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)

